MainWindow::MainWindow(rclcpp::Node::SharedPtr node, QWidget * parent)
: QMainWindow(parent),
  node_(node),
  ui_(std::make_unique<Ui::MainWindow>()),
  ros_bridge_(new RosBridge(node, this)),
  rviz_widget_(nullptr),
  camera_view_widget_(nullptr),
  ros_spin_timer_(nullptr) {
  buildUi();
  connectSignals();
  loadSelectedTree();
  ros_spin_timer_ = new QTimer(this);
  connect(ros_spin_timer_, &QTimer::timeout, this, [this]() {
    rclcpp::spin_some(node_); 
  });
  ros_spin_timer_->start(20);
}

MainWindow::~MainWindow() = default;

void MainWindow::buildUi() {
  ui_->setupUi(this);
  show_developer_tasks_checkbox_ = ui_->show_developer_tasks_checkbox;
  task_selector_ = ui_->task_selector;
  tcp_offset_spinbox_ = ui_->tcp_offset_spinbox;
  treatment_duration_spinbox_ = ui_->treatment_duration_spinbox;
  distance_guard_spinbox_ = ui_->distance_guard_spinbox;
  treatment_status_label_ = ui_->treatment_status_label;
  zero_button_ = ui_->zero_button;
  force_mode_combo_ = ui_->force_mode_combo;
  start_button_ = ui_->start_button;
  cancel_button_ = ui_->cancel_button;
  force_label_ = ui_->force_label;
  distance_label_ = ui_->distance_label;
  state_label_ = ui_->state_label;
  active_node_label_ = ui_->active_node_label;
  bt_tree_widget_ = ui_->bt_tree_widget;
  log_text_ = ui_->log_text;
  populateTaskSelector(false);
  bt_tree_widget_->setColumnCount(2);
  bt_tree_widget_->setHeaderLabels({"BT Node", "Status"});
  // bt_tree_widget_->header()->setSectionResizeMode(QHeaderView::Stretch);
  bt_tree_widget_->header()->setSectionResizeMode(QHeaderView::Interactive);
  log_text_->setReadOnly(true);
  rviz_widget_ = new RvizWidget(ui_->rviz_container);
  auto * rviz_layout = ui_->rviz_container->layout();
  if (!rviz_layout) {
    rviz_layout = new QVBoxLayout(ui_->rviz_container);
    rviz_layout->setContentsMargins(0, 0, 0, 0);
  }
  rviz_layout->addWidget(rviz_widget_);
  camera_view_widget_ = new CameraViewWidget(node_, ui_->camera_container);
  camera_view_widget_->setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);
  auto * camera_layout = ui_->camera_container->layout();
  if (!camera_layout) {
    camera_layout = new QVBoxLayout(ui_->camera_container);
    camera_layout->setContentsMargins(0, 0, 0, 0);
  }
  camera_layout->addWidget(camera_view_widget_);
  force_plot_ = new RollingPlotWidget(this);
  force_plot_->setTitle("Force Z");
  force_plot_->setYAxisLabel("N");
  force_plot_->setYRange(-30.0, 5.0);
  force_plot_->setWindowSec(10.0);
  force_plot_->setReferenceLines({-3.0, -8.0, -13.0, -25.0});
  distance_plot_ = new RollingPlotWidget(this);
  distance_plot_->setTitle("UC4 Distance");
  distance_plot_->setYAxisLabel("mm");
  distance_plot_->setYRange(40.0, 160.0);
  distance_plot_->setWindowSec(10.0);
  distance_plot_->setReferenceLines({distance_guard_spinbox_->value()});
  ui_->sensor_plot_layout->addWidget(force_plot_);
  ui_->sensor_plot_layout->addWidget(distance_plot_);
}

void MainWindow::connectSignals() {
  connect(zero_button_, &QPushButton::clicked, this, &MainWindow::onZeroClicked);
  connect(start_button_, &QPushButton::clicked, this, &MainWindow::onStartClicked);
  connect(cancel_button_, &QPushButton::clicked, this, &MainWindow::onCancelClicked);
  connect(task_selector_, qOverload<int>(&QComboBox::currentIndexChanged), this, [this](int) {
    loadSelectedTree(); 
  });
  connect(show_developer_tasks_checkbox_, &QCheckBox::toggled, this, &MainWindow::populateTaskSelector);
  connect(ros_bridge_, &RosBridge::taskStateUpdated, this, &MainWindow::onTaskStateUpdated);
  connect(ros_bridge_, &RosBridge::btNodeStatusUpdated, this, &MainWindow::onBtNodeStatusUpdated);
  connect(ros_bridge_, &RosBridge::logMessage, this, &MainWindow::onLogMessage);
  connect(ros_bridge_, &RosBridge::forceUpdated, this, [this](const QString & msg) {
    onForceUpdated(msg);
    bool ok = false;
    const double force_z = msg.toDouble(&ok);  
    if (ok && force_plot_) {
      force_plot_->addSample(force_z);
    }
  });
  connect(ros_bridge_, &RosBridge::distanceUpdated, this, [this](const QString & msg) {
    onDistanceUpdated(msg);
    bool ok = false;
    const double distance_mm = msg.toDouble(&ok);
    if (ok && distance_plot_) {
      distance_plot_->addSample(distance_mm);
    }
  });
  connect(ros_bridge_, &RosBridge::treatmentStatusUpdated, this, &MainWindow::onTreatmentUpdated);
  connect(distance_guard_spinbox_, qOverload<double>(&QDoubleSpinBox::valueChanged), this, [this](double value_mm) {
    if (distance_plot_) {
      distance_plot_->setReferenceLines({value_mm}); 
    }
  });
}

QString MainWindow::selectedTaskName() const {
  return task_selector_->currentText();
}

QString MainWindow::selectedTreePath() const {
  return treePathFor(selectedTaskName());
}

QString MainWindow::treePathFor(const QString & task) const {
  const auto share_dir = QString::fromStdString(ament_index_cpp::get_package_share_directory("tms_robot_control"));
  if (task == "move_arm_ready") {
    return share_dir + "/tree/move_arm_ready.xml";
  }
  if (task == "move_arm_above_head") {
    return share_dir + "/tree/move_arm_above_head.xml";
  }
  if (task == "move_to_tcp_target_offset") {
    return share_dir + "/tree/move_to_tcp_target_offset.xml";
  }
  if (task == "contact_treatment_test") {
    return share_dir + "/tree/contact_treatment_test.xml";
  }
  if (task == "retract_from_contact") {
    return share_dir + "/tree/retract_from_contact.xml";
  }
  if (task == "move_arm_up") {
    return share_dir + "/tree/move_arm_up.xml";
  }
  if (task == "treatment_inputs_fresh_test") {
    return share_dir + "/tree/treatment_inputs_fresh_test.xml";
  }
  if (task == "sensor_snapshot_test") {
    return share_dir + "/tree/sensor_snapshot_test.xml";
  }
  if (task == "sensor_watch_test") {
    return share_dir + "/tree/sensor_watch_test.xml";
  }
  if (task == "wait_for_target_pose_test") {
    return share_dir + "/tree/wait_for_target_pose_test.xml";
  }
  if (task == "move_tcp_relative") {
    return share_dir + "/tree/move_tcp_relative_z_test.xml";
  }
  return "";
}

void MainWindow::loadSelectedTree() {
  loaded_tree_task_ = selectedTaskName();
  loadTreeIntoWidget(selectedTreePath());
}

void MainWindow::onZeroClicked() {
  ros_bridge_->zeroFTS();
}

void MainWindow::onStartClicked() {
  if (selectedTaskName() == "demo_operator") {
    startDemoOperator();
    return;
  }
  const double tcp_offset_z_mm = tcp_offset_spinbox_->value();
  const double treatment_duration_sec = treatment_duration_spinbox_->value();
  const double min_distance_mm = distance_guard_spinbox_->value();
  QString force_mode = "LIGHT";
  if (force_mode_combo_->currentText() == "Heavy Press") {
    force_mode = "HEAVY";
  }
  if (distance_plot_) {
    distance_plot_->setReferenceLines({distance_guard_spinbox_->value()});
  }
  onLogMessage("Start task: " + selectedTaskName());
  ros_bridge_->startTask(
    selectedTaskName(),
    tcp_offset_z_mm,
    treatment_duration_sec,
    min_distance_mm,
    force_mode);
}

void MainWindow::onCancelClicked() {
  onLogMessage("Cancel button pressed");
  // Operator cancel outranks the demo loop: stop the script first so it sends
  // no further goals, then cancel the goal currently running in the executor.
  if (demo_process_ && demo_process_->state() != QProcess::NotRunning) {
    ::kill(static_cast<pid_t>(demo_process_->processId()), SIGINT);
  }
  ros_bridge_->cancelTask();
}

void MainWindow::startDemoOperator() {
  if (demo_process_ && demo_process_->state() != QProcess::NotRunning) {
    onLogMessage("demo_operator already running");
    return;
  }
  if (!demo_process_) {
    demo_process_ = new QProcess(this);
    demo_process_->setProcessChannelMode(QProcess::MergedChannels);
    connect(demo_process_, &QProcess::readyReadStandardOutput, this, [this]() {
      static const QRegularExpression ansi("\x1b\\[[0-9;]*m");
      const auto chunk = QString::fromUtf8(demo_process_->readAllStandardOutput());
      for (auto line : chunk.split('\n', Qt::SkipEmptyParts)) {
        onLogMessage(line.remove(ansi));
      }
    });
    connect(demo_process_,
      qOverload<int, QProcess::ExitStatus>(&QProcess::finished), this,
      [this](int, QProcess::ExitStatus) { onLogMessage("demo_operator stopped"); });
  }
  // Run the executable directly: `ros2 run` swallows SIGINT instead of
  // forwarding it to its child, so the Cancel button could never stop the loop.
  const auto exe = QString::fromStdString(
    ament_index_cpp::get_package_prefix("tms_robot_bringup") + "/lib/tms_robot_bringup/demo_operator");
  demo_process_->start(exe, QStringList{});
  onLogMessage("demo_operator started");
}

void MainWindow::onTaskStateUpdated(const QString & task_name,
  const QString & overall_state,
  const QString & active_node,
  const QString & message) {
  Q_UNUSED(message);
  // The demo drives several tasks; follow the executor's current tree so the
  // node status view is not stuck on the (tree-less) "demo_operator" entry.
  if (selectedTaskName() == "demo_operator" &&
      !task_name.isEmpty() && task_name != loaded_tree_task_) {
    loaded_tree_task_ = task_name;
    loadTreeIntoWidget(treePathFor(task_name));
  }
  state_label_->setText("State: " + overall_state);
  active_node_label_->setText("Active Node: " + active_node);
}

void MainWindow::onBtNodeStatusUpdated(const QString & node_name,
  const QString &,
  const QString & status) {
  if (!node_items_.contains(node_name)) {
    return;
  }
  auto * item = node_items_[node_name];
  item->setText(1, status);
  setItemColor(item, status);
}

void MainWindow::onLogMessage(const QString & msg) {
  const auto now = QDateTime::currentDateTime().toString("hh:mm:ss");
  log_text_->append(QString("[%1] %2").arg(now, msg));
  // Mirror to stdout so the panel log ends up in the bringup session log
  // (~/tms_session_logs) for post-hoc debugging in the clinic.
  std::cout << "[ui] " << msg.toStdString() << std::endl;
}

void MainWindow::onForceUpdated(const QString & msg) {
  force_label_->setText("Force sensor Z: " + msg + " N");
}

void MainWindow::onDistanceUpdated(const QString & msg) {
  distance_label_->setText("Distance sensor: " + msg + " mm");
}

void MainWindow::onTreatmentUpdated(const QString & msg) {
  treatment_status_label_->setText("Treatment: " + msg);
}

void MainWindow::loadTreeIntoWidget(const QString & xml_path) {
  bt_tree_widget_->clear();
  node_items_.clear();
  if (xml_path.isEmpty()) {
    return;
  }
  QFile file(xml_path);
  if (!file.open(QIODevice::ReadOnly)) {
    return;
  }
  QDomDocument doc;
  if (!doc.setContent(&file)) {
    return;
  }
  const auto root = doc.documentElement();
  QDomElement tree_elem;
  auto child = root.firstChild();
  while (!child.isNull()) {
    if (child.isElement() && child.toElement().tagName() == "BehaviorTree") {
      tree_elem = child.toElement();
      break;
    }
    child = child.nextSibling();
  }
  if (tree_elem.isNull()) {
    return;
  }
  auto node = tree_elem.firstChild();
  while (!node.isNull()) {
    if (node.isElement()) {
      auto * top = buildTreeItemFromDom(node.toElement());
      if (top) {
        bt_tree_widget_->addTopLevelItem(top);
      }
    }
    node = node.nextSibling();
  }
  bt_tree_widget_->expandAll();
}

QTreeWidgetItem * MainWindow::buildTreeItemFromDom(const QDomElement & element) {
  QString node_name = element.hasAttribute("name")
    ? element.attribute("name")
    : element.tagName();
  auto * item = new QTreeWidgetItem({node_name, "IDLE" });
  node_items_[node_name] = item;
  auto child = element.firstChild();
  while (!child.isNull()) {
    if (child.isElement()) {
      auto * sub = buildTreeItemFromDom(child.toElement());
      if (sub) {
        item->addChild(sub);
      }
    }
    child = child.nextSibling();
  }
  return item;
}

void MainWindow::setItemColor(QTreeWidgetItem * item, const QString & status) {
  QColor color = Qt::white;
  if (status == "RUNNING") {
    color = QColor(255, 235, 130);
  } 
  else if (status == "SUCCESS") {
    color = QColor(170, 255, 170);
  } 
  else if (status == "FAILURE") {
    color = QColor(255, 170, 170);
  }
  item->setBackground(0, QBrush(color));
  item->setBackground(1, QBrush(color));
}

void MainWindow::populateTaskSelector(bool show_developer_tasks) {
  const QString current_task = task_selector_->currentText();
  task_selector_->clear();
  task_selector_->addItem("move_arm_ready");
  task_selector_->addItem("move_arm_above_head");
  task_selector_->addItem("move_to_tcp_target_offset");
  task_selector_->addItem("contact_treatment_test");
  task_selector_->addItem("retract_from_contact");
  task_selector_->addItem("demo_operator");
  if (show_developer_tasks) {
    task_selector_->insertSeparator(task_selector_->count());
    task_selector_->addItem("move_arm_up");
    task_selector_->addItem("treatment_inputs_fresh_test");
    task_selector_->addItem("sensor_snapshot_test");
    task_selector_->addItem("sensor_watch_test");
    task_selector_->addItem("wait_for_target_pose_test");
    task_selector_->addItem("move_tcp_relative");
  }
  const int index = task_selector_->findText(current_task);
  if (index >= 0) {
    task_selector_->setCurrentIndex(index);
  } 
  else {
    loadSelectedTree();
  }
}